WHERE l.wecom_external_userid = #{wecomExternalUserid}
ORDER BY l.create_time DESC
LIMIT 1


WHERE sid = #{sid} AND mobile_phone = #{mobilePhone}
ORDER BY create_time DESC
LIMIT 1


WHERE l.mobile_phone = #{mobilePhone}
ORDER BY l.create_time DESC
LIMIT 1


WHERE l.sid = #{sid}
  AND (
      (l.wechat_mp_openid = #{openId}

       AND l.wechat_mp_app_id = #{appId}

      )
      OR l.custom_field::jsonb->>'wechat_mp_openid' = #{openId}
      OR l.contact_id IN (
          SELECT contact_id FROM crm_customer_identity
          WHERE identity_type = 'wechat_mp_openid' AND identity_value = #{openId}
      )
  )
ORDER BY l.create_time DESC
LIMIT 1

SELECT COUNT(*)
FROM crm_lead
WHERE mobile_phone = #{mobilePhone}
  AND lower(trim(coalesce(status, ''))) = 'assigned'
  AND user_id IS NOT NULL

      AND lead_id <> #{excludeLeadId}




     and l.org_id = #{orgId}
     and l.dept_id = #{deptId}
     and l.lead_name ILIKE concat('%', #{leadName}, '%')
     and l.mobile_phone = #{mobilePhone}
     and l.lead_source = #{leadSource}
     and l.stage = #{stage}

        and lower(trim(coalesce(l.status, ''))) in ('open', 'initial')


        and l.user_id = #{currentUserId}
        and lower(trim(coalesce(l.status, ''))) not in ('converted', 'open', 'initial')


        and lower(trim(coalesce(l.status, ''))) = 'assigned'


        and lower(trim(coalesce(l.status, ''))) in ('open', 'assigned')


        and lower(trim(coalesce(l.status, ''))) = 'converted'
        and l.user_id = #{currentUserId}


        and 1=1

    ${params.dataScope}

order by l.create_time desc



    and lower(trim(coalesce(l.status, ''))) = 'converted'
     and l.user_id = #{currentUserId}
     and l.lead_type = #{leadType}
     and l.lead_name ILIKE concat('%', #{leadName}, '%')
     and l.mobile_phone = #{mobilePhone}
     and l.owner ILIKE concat('%', #{owner}, '%')
     and l.contact_id = #{contactId}
     and l.convert_time >= #{convertTimeFrom}
     and l.convert_time <= #{convertTimeTo}
    ${params.dataScope}

order by l.convert_time desc nulls last, l.create_time desc

SELECT lead_id, status, user_id, owner, last_followup_at, assigned_at, create_time
FROM crm_lead
WHERE lower(trim(coalesce(status, ''))) = 'assigned'
  AND user_id = #{userId}
ORDER BY last_followup_at ASC NULLS FIRST, assigned_at ASC NULLS FIRST, create_time ASC
LIMIT #{excess}

