UPDATE crm_lead
SET last_followup_at = #{lastFollowupAt}
WHERE lead_id = #{leadId}

mapper.select:

WHERE lower(trim(coalesce(l.status, ''))) <> 'converted'

    AND l.lead_id <> #{excludeLeadId}

AND (
    1 = 0

        OR regexp_replace(coalesce(l.mobile_phone, ''), '[^0-9]', '', 'g') = #{mobilePhone}


        OR l.wecom_external_userid = #{wecomExternalUserid}


        OR regexp_replace(coalesce(l.work_phone, ''), '[^0-9]', '', 'g') = #{workPhone}


        OR lower(trim(coalesce(l.work_email, ''))) = #{workEmail}


        OR l.custom_field::jsonb->>'wechat' = #{wechat}
        OR l.custom_field::jsonb->>'wechat_id' = #{wechat}

)
ORDER BY l.create_time DESC
LIMIT 1

SELECT lead_id, lead_name, full_name, contact_id, contact_name, mobile_phone, work_phone,
       stage, status, create_time, update_time, user_id, owner
FROM crm_lead
WHERE create_time >= #{createdFrom}
  AND create_time < #{createdTo}
  AND (
      (contact_id IS NOT NULL AND TRIM(contact_id) <> '')
      OR (mobile_phone IS NOT NULL AND TRIM(mobile_phone) <> '')
  )
ORDER BY create_time ASC
LIMIT #{limit}
